# ---------------------------------------------------------------------------
# Action / facing constants.
# ---------------------------------------------------------------------------

ACTION_INTERACT = 5

FACING_UP = 0
FACING_DOWN = 1
FACING_RIGHT = 2
FACING_LEFT = 3

# facing id -> movement action that produces that facing.
_FACING_TO_ACTION = [3, 1, 0, 2]


def _localize(obs):
    static = obs[:, :, 20:29]
    cand = jnp.asarray(_CAND_CROPS, dtype=jnp.int32)
    diffs = jnp.sum(jnp.abs(static[None, :, :, :] - cand), axis=(1, 2, 3))
    return jnp.argmin(diffs).astype(jnp.int32)


def _current_facing(obs):
    return jnp.argmax(obs[2, 2, 1:5]).astype(jnp.int32)


def _navigate_or_interact(self_idx, approach_idx, required_facing, nav_next, current_facing):
    facing_to_action = jnp.asarray(_FACING_TO_ACTION, dtype=jnp.int32)
    at_target = self_idx == approach_idx
    turn_action = facing_to_action[required_facing]
    action = jnp.where(
        at_target,
        jnp.where(current_facing == required_facing, ACTION_INTERACT, turn_action),
        nav_next,
    )
    return action.astype(jnp.int32)


# ---------------------------------------------------------------------------
# agent_0: recipe-aware ingredient supplier.
# ---------------------------------------------------------------------------

# Only a *correct* delivery resamples the recipe, and that happens several
# steps after the pot the dish came from is scooped empty (the collector
# still has to walk to the delivery station and interact), so an ingredient
# added to the pot can be based on a target that is about to change:
#  - The *first* unit of a fresh batch is guarded by a short wait right at
#    the empty pot (long enough for the self-play collector's minimal
#    delivery travel to resolve any pending resample) before it is
#    committed; a flip discovered during that wait diverts the held item to
#    be trashed instead of added.
#  - A resample can in principle still land between later units of the same
#    batch (it is driven by an independent, already in-flight delivery of
#    the *previous* batch, not by this batch's own fill progress), and
#    because there is no pot-trash action a stale unit already sitting in
#    the pot can never be un-added. So the invariant that actually matters
#    is checked directly against the pot's own contents (not just the held
#    item): agent_0 never adds an ingredient unless the pot is empty or
#    already holds only that same type, and if it ever finds the pot
#    holding a type it cannot currently supply, it switches to fetching and
#    adding *that* type instead, to drain the stuck pot as fast as possible
#    rather than compounding the mix or blocking on it forever.
_POT_CLEAR_WAIT = 2


def init_agent_0():
    return {
        'target': jnp.asarray(0, dtype=jnp.int32),
        'has_target': jnp.asarray(0, dtype=jnp.int32),
        'drain_type': jnp.asarray(2, dtype=jnp.int32),
        'wait_counter': jnp.asarray(0, dtype=jnp.int32),
    }


def agent_0_act(obs, reset, memory, rng):
    del rng
    prev_target = jnp.where(reset, jnp.asarray(0, jnp.int32), memory['target'])
    prev_has_target = jnp.where(reset, jnp.asarray(0, jnp.int32), memory['has_target'])
    prev_drain = jnp.where(reset, jnp.asarray(2, jnp.int32), memory['drain_type'])
    prev_wait = jnp.where(reset, jnp.asarray(0, jnp.int32), memory['wait_counter'])

    self_idx = _localize(obs)

    recipe_mask = obs[:, :, 23]
    ing0_disp = obs[:, :, 36]
    ing1_disp = obs[:, :, 37]
    visible0 = jnp.any((recipe_mask == 1) & (ing0_disp == 3))
    visible1 = jnp.any((recipe_mask == 1) & (ing1_disp == 3))
    new_target = jnp.where(visible0, 0, jnp.where(visible1, 1, prev_target)).astype(jnp.int32)
    new_has_target = jnp.where(visible0 | visible1, 1, prev_has_target).astype(jnp.int32)

    at_pot = self_idx == _IDX_POT0
    pot_ing0 = obs[2, 3, 31]
    pot_ing1 = obs[2, 3, 32]
    pot_ing2 = obs[2, 3, 33]
    pot_ing_total = pot_ing0 + pot_ing1 + pot_ing2
    pot_cooked = obs[2, 3, 30]
    pot_full_or_cooking = (pot_ing_total >= 3) | (pot_cooked == 1)
    pot_is_empty = pot_ing_total == 0
    pot_is_partial = jnp.logical_not(pot_full_or_cooking) & jnp.logical_not(pot_is_empty)
    pot_existing_type = jnp.where(pot_ing0 > 0, 0, jnp.where(pot_ing1 > 0, 1, jnp.asarray(2, jnp.int32))).astype(jnp.int32)

    # Track whatever type is currently stuck in the pot and needs draining
    # (differs from the live recipe target), refreshed whenever agent_0 is
    # actually at the pot to see it; stale/irrelevant elsewhere since only
    # agent_0 ever changes pot contents.
    drain_from_partial = jnp.where(pot_existing_type != new_target, pot_existing_type, jnp.asarray(2, jnp.int32))
    new_drain = jnp.where(
        at_pot,
        jnp.where(pot_is_partial, drain_from_partial, jnp.where(pot_is_empty, jnp.asarray(2, jnp.int32), prev_drain)),
        prev_drain,
    ).astype(jnp.int32)

    effective_target = jnp.where(new_drain != 2, new_drain, new_target).astype(jnp.int32)

    ing0 = obs[2, 2, 7]
    ing1 = obs[2, 2, 8]
    ing2 = obs[2, 2, 9]
    holding_ingredient = (ing0 + ing1 + ing2) > 0
    held_type = jnp.where(ing0 > 0, 0, jnp.where(ing1 > 0, 1, 2)).astype(jnp.int32)
    have_real_target = (new_has_target == 1) | (new_drain != 2)
    mismatched = holding_ingredient & have_real_target & (held_type != effective_target) & (held_type != 2)

    # target_id: 0/1 = go fetch ingredient0/1 (or go trash a mismatched one
    # of that type); 2 = go add the held ingredient to the pot; 3 = stand by
    # at the pot without adding because it holds a type incompatible with
    # what's in hand right now (a same-step safety net; normally prevented
    # before it happens by the drain-type tracking above, which redirects
    # the next fetch).
    add_blocked_by_pot = (
        holding_ingredient & jnp.logical_not(mismatched) & at_pot
        & (pot_existing_type != 2) & (pot_existing_type != held_type)
    )

    target_id = jnp.where(
        holding_ingredient,
        jnp.where(mismatched, held_type, jnp.where(add_blocked_by_pot, jnp.asarray(3, jnp.int32), jnp.asarray(2, jnp.int32))),
        effective_target,
    ).astype(jnp.int32)

    ing0_leftover = obs[1, 2, 31] > 0
    ing1_leftover = obs[3, 2, 32] > 0

    desired_facing0 = jnp.where(holding_ingredient | ing0_leftover, FACING_UP, FACING_LEFT)
    desired_facing1 = jnp.where(holding_ingredient | ing1_leftover, FACING_DOWN, FACING_LEFT)

    required_facing = jnp.where(
        target_id == 0, desired_facing0,
        jnp.where(target_id == 1, desired_facing1, FACING_RIGHT),
    ).astype(jnp.int32)

    approach_idx = jnp.where(
        target_id == 0, _IDX_ING0,
        jnp.where(target_id == 1, _IDX_ING1, _IDX_POT0),
    ).astype(jnp.int32)

    table_ing0 = jnp.asarray(_TABLE_ING0, dtype=jnp.int32)
    table_ing1 = jnp.asarray(_TABLE_ING1, dtype=jnp.int32)
    table_pot0 = jnp.asarray(_TABLE_POT0, dtype=jnp.int32)
    nav0 = table_ing0[self_idx]
    nav1 = table_ing1[self_idx]
    nav2 = table_pot0[self_idx]
    nav_next = jnp.where(target_id == 0, nav0, jnp.where(target_id == 1, nav1, nav2)).astype(jnp.int32)

    current_facing = _current_facing(obs)
    action = _navigate_or_interact(self_idx, approach_idx, required_facing, nav_next, current_facing)
    action = jnp.where(target_id == 3, jnp.asarray(4, jnp.int32), action).astype(jnp.int32)

    # Short post-hoc wait, gated on the actual interact this step would
    # perform: the first unit of a fresh batch (pot currently empty) is
    # delayed a couple of steps before it is actually committed, long
    # enough for the self-play collector's minimal delivery travel to
    # resolve any pending resample first; a flip discovered during the wait
    # is caught by the mismatch check above on a later step, before this
    # gate is ever reached again.
    about_to_add_to_empty = (action == ACTION_INTERACT) & (target_id == 2) & pot_is_empty
    should_delay_empty_add = about_to_add_to_empty & (prev_wait < _POT_CLEAR_WAIT)
    action = jnp.where(should_delay_empty_add, jnp.asarray(4, jnp.int32), action).astype(jnp.int32)
    new_wait = jnp.where(
        about_to_add_to_empty,
        jnp.where(prev_wait < _POT_CLEAR_WAIT, prev_wait + 1, jnp.asarray(0, jnp.int32)),
        jnp.asarray(0, jnp.int32),
    ).astype(jnp.int32)

    next_memory = {
        'target': new_target,
        'has_target': new_has_target,
        'drain_type': new_drain,
        'wait_counter': new_wait,
    }
    trace = {
        'self_idx': self_idx,
        'target_id': target_id,
        'action': action,
    }
    return action, next_memory, trace


# ---------------------------------------------------------------------------
# agent_1: plate / scoop / deliver. Never sees the recipe indicator, so it
# never guesses ingredient types; it only ever handles plates and dishes.
# ---------------------------------------------------------------------------

def init_agent_1():
    return jnp.asarray(0, dtype=jnp.int32)


def agent_1_act(obs, reset, memory, rng):
    del rng
    self_idx = _localize(obs)

    plate = obs[2, 2, 5]
    cooked = obs[2, 2, 6]
    ing_sum = obs[2, 2, 7] + obs[2, 2, 8] + obs[2, 2, 9]
    empty_hands = (plate == 0) & (cooked == 0) & (ing_sum == 0)
    holding_plate_only = (plate == 1) & (cooked == 0)

    target_id = jnp.where(empty_hands, 0, jnp.where(holding_plate_only, 1, 2)).astype(jnp.int32)

    required_facing = jnp.where(
        target_id == 0, FACING_RIGHT,
        jnp.where(target_id == 1, FACING_LEFT, FACING_RIGHT),
    ).astype(jnp.int32)

    approach_idx = jnp.where(
        target_id == 0, _IDX_PLATE,
        jnp.where(target_id == 1, _IDX_POT1, _IDX_DELIVER),
    ).astype(jnp.int32)

    table_plate = jnp.asarray(_TABLE_PLATE, dtype=jnp.int32)
    table_pot1 = jnp.asarray(_TABLE_POT1, dtype=jnp.int32)
    table_deliver = jnp.asarray(_TABLE_DELIVER, dtype=jnp.int32)
    nav0 = table_plate[self_idx]
    nav1 = table_pot1[self_idx]
    nav2 = table_deliver[self_idx]
    nav_next = jnp.where(target_id == 0, nav0, jnp.where(target_id == 1, nav1, nav2)).astype(jnp.int32)

    current_facing = _current_facing(obs)
    action = _navigate_or_interact(self_idx, approach_idx, required_facing, nav_next, current_facing)

    next_memory = jnp.where(reset, jnp.asarray(0, jnp.int32), jnp.asarray(0, jnp.int32))
    trace = {
        'self_idx': self_idx,
        'target_id': target_id,
        'action': action,
    }
    return action, next_memory, trace
